            reject: [{ re: 'false|wrong|useless|worthless', hint: 'A limit makes the point smaller, not false. Keep your position.' },
              { re: '^(for|because|as)\\b', hint: 'The limit leads to this, so the linker shows a result.' },
              { re: 'this points', hint: 'After "this" the noun is singular.' }],
